// ============================================
// DETECT INTENT (RFC-007)
// Utilise des patterns pour pré-classification
// Le LLM affine ensuite pour 'question'
// ============================================

const input = $input.first().json;
const content = (input.data?.content || '').trim().toLowerCase();

// --- Patterns de détection ---
const PATTERNS = {
  greeting: /^(bonjour|salut|hello|hey|coucou|bonsoir|yo|hi|bjr|slt)\b/i,
  help: /^(aide|help|commandes?|comment (ça marche|utiliser|faire)|\?\?\?)$/i,
  empty: /^\s*$/
};

// --- Détection par patterns ---
let intent = 'question';  // Default: envoyer au LLM
let confidence = 0.5;
let skip_llm = false;

if (PATTERNS.empty.test(content)) {
  intent = 'empty';
  confidence = 1.0;
  skip_llm = true;
} else if (PATTERNS.greeting.test(content)) {
  intent = 'greeting';
  confidence = 0.95;
  skip_llm = true;
} else if (PATTERNS.help.test(content)) {
  intent = 'help';
  confidence = 0.95;
  skip_llm = true;
}

return {
  project_id: input.project_id,
  data: input.data,
  detected_intent: intent,
  confidence: confidence,
  skip_llm: skip_llm
};

// ============================================
// PREDEFINED RESPONSES (RFC-007)
// Pour greeting, help, empty
// ============================================

const input = $input.first().json;
const intent = input.detected_intent;
const displayName = input.data?.display_name || 'ami';

const RESPONSES = {
  greeting: {
    response: `Bonjour ${displayName} ! Comment puis-je t'aider ? Pose-moi une question culinaire ou tape /help pour voir les commandes.`,
    intent: 'greeting',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  },
  help: {
    response: `Voici ce que je peux faire :\n• Répondre à tes questions culinaires\n• \`/recette [nom]\` - Chercher une recette\n• \`/liste\` - Voir ta liste de courses\n• \`/panier\` - Gérer ton panier\n\nMentionne-moi avec ta question !`,
    intent: 'help',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  },
  empty: {
    response: `Tu m'as mentionné mais sans message ! Pose-moi une question culinaire ou tape /help pour voir ce que je peux faire.`,
    intent: 'empty',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  }
};

const result = RESPONSES[intent] || RESPONSES.empty;

return {
  success: true,
  ...result,
  project_id: input.project_id,
  user_id: input.data?.user_id
};

