// ============================================
// FORMAT LLM SUCCESS RESPONSE
// ============================================

const input = $input.first().json;
const validationData = $('Detect Intent').first().json;

// Calcul crédits consommés (formule hybride RFC-007)
const tokensUsed = input.tokens_used || 0;
const intent = input.intent || 'question';

// Table de coûts
const COSTS = {
  recette: { base: 3, rate: 1.0, max: 10 },
  question: { base: 1, rate: 0.5, max: 5 },
  liste_ingredients: { base: 2, rate: 0.5, max: 5 },
  default: { base: 1, rate: 0.5, max: 5 }
};

const cost = COSTS[intent] || COSTS.default;
const creditsConsumed = Math.min(
  cost.base + (tokensUsed / 1000) * cost.rate,
  cost.max
);

return {
  success: true,
  response: input.response,
  intent: intent,
  confidence: input.confidence || 0.9,
  tokens_used: tokensUsed,
  credits_consumed: Math.ceil(creditsConsumed),
  project_id: validationData.project_id,
  user_id: validationData.data?.user_id
};

// ============================================
// FORMAT LLM ERROR / FALLBACK
// ============================================

const input = $input.first().json;
const validationData = $('Detect Intent').first().json;

// Vérifier si c'est out_of_scope ou erreur
const isOutOfScope = input.intent === 'out_of_scope';
const isUnknown = !input.response;

let response;
let intent;

if (isOutOfScope) {
  response = input.response || "Je suis spécialisé en cuisine ! Cette question est hors de mon domaine. Pose-moi une question culinaire !";
  intent = 'out_of_scope';
} else if (isUnknown) {
  response = "Je n'ai pas bien compris ta demande. Peux-tu reformuler ou taper /help ?";
  intent = 'unknown';
} else {
  response = "Désolé, je n'ai pas pu traiter ta demande. Réessaie dans quelques instants.";
  intent = 'error';
}

return {
  success: true,
  response: response,
  intent: intent,
  confidence: 0.5,
  tokens_used: 0,
  credits_consumed: 0,
  project_id: validationData.project_id,
  user_id: validationData.data?.user_id
};
